import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"immune-strength-calculator":{title:'Immune Strength Calculator',sections:[
{heading:'What this score can and cannot tell you',text:['An immune-strength score is best treated as a lifestyle screening summary, not a laboratory measurement of immunity.', 'Sleep, diet quality, activity, stress, smoking, alcohol, age and medicines can influence infection risk or immune function in different ways, but they cannot be collapsed into a clinically validated percentage of “immune strength.” Use the result to identify modifiable habits, not to diagnose immune deficiency.']},
{heading:'Sleep and immune function',text:['Sleep duration and regularity matter because immune signaling, antibody responses and recovery are linked with adequate sleep.', 'A single short night is different from chronic restriction. When using the calculator, enter a typical pattern rather than an unusually good or bad night, and interpret a low sleep contribution as a prompt to improve consistency rather than proof of disease.']},
{heading:'Nutrition is more than one nutrient',text:['Protein and adequate energy support immune-cell turnover, while deficiencies of nutrients such as vitamin D, B12, folate, iron or zinc can matter in specific circumstances.', 'More is not automatically better: megadoses do not create proportionally stronger immunity. A diet pattern with sufficient protein, fruit, vegetables, whole grains and varied micronutrient sources is more informative than chasing one supplement.']},
{heading:'Exercise has a dose-response relationship',text:['Regular moderate activity is generally compatible with good immune and metabolic health, but very high training loads combined with inadequate recovery can increase fatigue and illness susceptibility.', 'Interpret exercise together with sleep, energy intake and recovery. The calculator should not reward extreme volume simply because some activity is beneficial.']},
{heading:'Stress, smoking and alcohol',text:['Persistent psychological stress can affect sleep and health behaviors, smoking exposes the respiratory tract to irritants and is associated with impaired host defenses, and heavy alcohol use can disrupt immune function.', 'These factors are not interchangeable points: a similar score can hide very different risk profiles, so inspect the individual inputs.']},
{heading:'When a calculator is not enough',text:['Frequent severe infections, unusual infections, persistent fever, unexplained weight loss or concerns about immunosuppressive medicines require clinical evaluation.', 'Vaccination status, chronic disease and prescribed treatments can matter more than a lifestyle score. Do not stop medication or substitute supplements based on this result.']},
]},
"joint-mobility-calculator":{title:"Joint Mobility Calculator",sections:[
{heading:"What this mobility score actually measures",text:["This calculator compares six entered ranges of motion with fixed reference values: 180° shoulder abduction, 120° hip flexion, 20° ankle dorsiflexion, 80° neck rotation, 45° thoracic rotation and 70° wrist extension. Each joint score is the entered angle divided by that reference and expressed as a percentage. The overall score is the simple average of those six percentages, so every joint contributes equally even though different activities place different demands on different joints.","Treat the result as a screening summary of the measurements you entered, not as a diagnosis of joint health, flexibility, instability or injury risk."]},
{heading:"How to measure range of motion consistently",text:["Range-of-motion numbers are only useful when the movement and measurement method stay consistent. Shoulder abduction should represent raising the arm out to the side without substituting excessive trunk lean. Hip flexion should avoid turning pelvic movement into extra apparent hip motion. Ankle dorsiflexion changes depending on whether the knee is bent or straight, while neck and thoracic rotation can be distorted by movement from neighboring regions.","For repeat tracking, use the same side, body position, warm-up, measuring device and landmark method each time. A phone inclinometer or goniometer can improve repeatability, but technique still matters."]},
{heading:"Understanding the six joint scores",text:["A 90% shoulder score means the entered shoulder abduction is about 90% of the calculator's 180° reference. The same interpretation applies to the hip, ankle, neck, thoracic spine and wrist. Scores above 100% are mathematically possible because the function does not cap individual joint percentages. Extra range is not automatically better: some people naturally have greater mobility, and excessive motion without adequate control may be undesirable for a particular sport or joint.","Use the joint-by-joint bars to find asymmetry in the profile rather than focusing only on the average."]},
{heading:"Why the tightest joint matters",text:["The calculator identifies the lowest percentage as the tightest joint and makes it the stretching priority. That is a convenient way to identify the largest deficit relative to these reference values, but the lowest percentage is not necessarily the cause of pain or the most important limitation for your activity. Limited ankle dorsiflexion may matter greatly for a deep squat, while limited wrist extension may matter more for front-rack positions, push-ups or gymnastics.","Choose priorities using both the score and the movement you are trying to perform."]},
{heading:"Age adjustment in this calculator",text:["The implemented formula adds five points to the overall score after age 45 and ten points after age 60. This is a simple age adjustment intended to make the summary less harsh as mobility commonly changes with age. It does not use joint-specific age norms, sex-specific reference ranges, medical history or population percentiles. The raw overall score therefore remains useful because it shows the direct comparison with the fixed references before this adjustment.","Do not interpret the age-adjusted number as a clinical percentile or proof that a restriction is normal for age."]},
{heading:"Worked mobility example",text:["Suppose shoulder abduction is 162°, hip flexion 108°, ankle dorsiflexion 12°, neck rotation 72°, thoracic rotation 40° and wrist extension 63°. Those values are roughly 90%, 90%, 60%, 90%, 89% and 90% of the calculator references. The average is about 85%, but the ankle clearly stands out at 60%. A person using this profile for squat training would learn more from the ankle deficit than from the respectable overall average.","After a mobility program, remeasure the ankle under the same conditions to see whether the change is real and repeatable."]},
{heading:"Mobility is not the same as flexibility or control",text:["Flexibility usually describes the extensibility of muscles and other tissues, whereas mobility is often used more broadly for usable movement at a joint or body region. A person can have passive range that they cannot actively control. Conversely, apparent restriction can come from pain, swelling, joint structure, neural sensitivity, protective muscle tone or measurement technique rather than simply a muscle that needs stretching.","That distinction matters because the calculator's automatic recommendation of a daily stretch cannot identify the mechanism behind a low measurement."]},
{heading:"Interpreting the injury-risk label cautiously",text:["The code labels an average below 60% as elevated injury risk and higher averages as within normal range. Real injury risk is more complex and depends on prior injury, workload, strength, balance, sport exposure, fatigue, tissue capacity and many other factors. A high mobility score does not guarantee protection from injury, and a low score does not mean an injury will occur.","Use the label as a prompt to investigate major restrictions, especially when they are new, painful, asymmetric or interfere with normal movement."]},
{heading:"When stretching is not the right response",text:["Do not force range through sharp pain, recent trauma, a swollen joint, neurological symptoms or a feeling of instability. In those situations, more stretching may be inappropriate. Even in pain-free training, improvements often come from combining mobility work with strength through the newly available range. For example, ankle mobility drills may be paired with controlled calf and squat work, while shoulder mobility may be paired with rotator-cuff and scapular control exercises.","The calculator cannot determine whether stretching, strengthening, technique changes or clinical assessment is the appropriate intervention."]},
{heading:"Best way to use this calculator over time",text:["Create a baseline rather than chasing a perfect 100% score. Record the actual angles, note the side tested, and repeat the same measurements every few weeks. Look for meaningful trends in the joint that matters to your activity. If a value jumps dramatically from one session to the next, suspect measurement variation before assuming the joint changed that quickly.","Persistent loss of motion, substantial left-right differences, pain, locking or limitation after injury deserves assessment by a qualified clinician rather than repeated self-testing alone."]},
]},
"real-estate-cost-basis-calculator":{title:'Real Estate Cost Basis Calculator',sections:[
{heading:'Start with acquisition basis',text:['For purchased property, basis generally begins with the amount paid for the property, then certain acquisition costs are added while items that are currently deductible are treated differently.', 'The calculator should separate land and building when depreciation is relevant because land is not depreciated.']},
{heading:'Capital improvements versus repairs',text:['A new roof, addition or major system replacement may increase basis when it materially improves or restores the property, while routine repairs may be currently deductible for a rental rather than capitalized.', 'Classification depends on facts and tax rules; saving invoices and dates is essential.']},
{heading:'Depreciation changes adjusted basis',text:['For depreciable real estate, adjusted basis is reduced by depreciation allowed or allowable.', 'That means basis used to estimate gain at sale can be lower than original cost even if the owner did not claim every deduction correctly. Depreciation recapture can also receive different tax treatment from the remaining gain.']},
{heading:'Selling costs and amount realized',text:['Basis is only one side of a sale calculation.', 'Gross selling price may be reduced by qualifying selling expenses to determine amount realized, and gain is broadly amount realized minus adjusted basis. Mortgage payoff affects cash received but generally is not simply subtracted from taxable gain as though it were basis.']},
{heading:'Special basis rules',text:['Inherited property may receive a basis tied to date-of-death value, gifts can carry donor basis with special loss rules, and like-kind exchanges can create deferred basis adjustments.', 'These situations should not be forced into a simple purchase-price-plus-improvements model.']},
{heading:'Records make the estimate defensible',text:['Closing statements, settlement disclosures, improvement invoices, depreciation schedules and prior tax returns are the core evidence behind a basis calculation.', 'Use the calculator as a reconciliation worksheet and verify the final tax basis with current jurisdiction-specific rules before a sale or filing.']},
]},
"migraine-risk-calculator":{title:'Migraine Risk Calculator',sections:[
{heading:'A risk score is not a migraine diagnosis',text:['Migraine is diagnosed from headache characteristics and associated symptoms, not from a generic percentage score.', 'The calculator can organize patterns such as headache frequency, sleep disruption, stress, caffeine changes and known triggers, but it cannot distinguish every migraine subtype or rule out secondary headache causes.']},
{heading:'Track frequency and disability separately',text:['Headache days per month, migraine days, attack duration and functional impairment answer different questions.', 'A person with fewer but disabling attacks may need as much attention as someone with frequent milder symptoms. A diary can capture timing, severity, medication use and missed activities more reliably than memory.']},
{heading:'Triggers are individual and probabilistic',text:['Sleep loss, skipped meals, dehydration, stress changes, alcohol, hormonal changes and some foods are reported triggers for some people, but a trigger is not universal and may require a combination of circumstances.', 'Avoid unnecessarily restrictive diets based on one coincidental attack.']},
{heading:'Caffeine can help or hurt',text:['Caffeine can enhance some acute headache treatments, while high habitual intake or abrupt withdrawal can provoke headaches.', 'Record both quantity and timing. The relevant pattern is often change from the person’s baseline rather than caffeine being inherently good or bad.']},
{heading:'Medication overuse matters',text:['Frequent use of acute headache medicines can contribute to medication-overuse headache depending on the drug and number of use days.', 'A risk calculator should not encourage repeated self-treatment without tracking medication days.']},
{heading:'Red flags need medical assessment',text:['A sudden “worst headache,” new neurological deficit, headache with fever or neck stiffness, new headache after major trauma, or a major change in pattern warrants prompt medical assessment.', 'The score should never delay evaluation of red-flag symptoms.']},
]},
"fortune-cookie":{title:'Fortune Cookie Generator',sections:[
{heading:'What the generator is doing',text:['A fortune-cookie generator selects or constructs a short message intended to feel playful, optimistic or reflective.', 'There is no financial forecast, probability model or predictive mechanism behind the output. The value of the tool is variety and tone, not accuracy about future events.']},
{heading:'Writing a convincing fortune',text:['Classic fortune-style lines are brief, self-contained and open enough to invite interpretation.', 'Concrete imagery can make a line memorable, while excessive specificity makes it sound like a false prediction. A good generator balances novelty with readable grammar.']},
{heading:'Randomness and repetition',text:['If messages are chosen from a fixed list, repeated results become more likely as users generate more fortunes.', 'Shuffling, avoiding the immediately previous item, or expanding the message pool can improve perceived variety without pretending the randomness is meaningful.']},
{heading:'Tone and safety',text:['Fortunes work best when they avoid threatening predictions, medical claims, financial promises or statements that could be mistaken for professional advice.', 'Humor can be whimsical without targeting protected traits or personal vulnerabilities.']},
{heading:'Localization and culture',text:['Idioms, lucky symbols and humor do not translate perfectly across cultures.', 'Localized fortune sets should be written for the target language rather than mechanically translated word-for-word.']},
{heading:'Using the output creatively',text:['A generated fortune can be used as a writing prompt, party-game line, placeholder message or lighthearted social caption.', 'Treat it as entertainment; if a line inspires a real decision, evaluate that decision on actual evidence rather than the generated sentence.']},
]},
"markdown-table-gen":{title:'Markdown Table Generator',sections:[
{heading:'Core Markdown table syntax',text:['A common Markdown table uses a header row, a delimiter row made with hyphens, and zero or more body rows separated by vertical bars.', 'The delimiter row is what makes the structure a table in GitHub-Flavored Markdown and many compatible renderers.']},
{heading:'Alignment markers',text:['Colons in the delimiter row commonly request alignment: a colon on the left means left alignment, on both sides means centered, and on the right means right alignment.', 'Renderer support can vary, so preview the exact Markdown flavor used by the destination.']},
{heading:'Escaping pipe characters',text:['A literal vertical bar inside a cell can be mistaken for a column separator.', 'In renderers that support it, escape the pipe with a backslash or use an alternative representation. Generated output should preserve the intended number of columns on every row.']},
{heading:'Multiline and rich content limitations',text:['Standard pipe-table syntax is poor at representing multiline cell content, nested block elements or complex HTML.', 'For documentation with complex cells, an HTML table or a different presentation may be more reliable than forcing everything into Markdown.']},
{heading:'Readable source matters',text:['Column padding is optional for rendering but useful for humans editing the source.', 'A generator can normalize spacing while leaving cell text unchanged. Do not trim meaningful spaces inside code-like content without warning.']},
{heading:'Accessibility and semantics',text:['Markdown renderers typically convert the first row to table headers, which gives useful semantics, but accessibility still depends on the generated HTML and surrounding context.', 'Add a clear introduction when the table’s purpose is not obvious, and avoid using tables solely for visual page layout.']},
]},
"investment-property-leverage-calculator":{title:"Investment Property Leverage Calculator",sections:[
{heading:"What leverage changes in a property investment",text:["Leverage means controlling a property with a combination of investor equity and borrowed money. This calculator starts with property value and down-payment percentage, then treats the remainder as a 30-year mortgage. Because the investor contributes only the down payment as initial equity, appreciation and principal repayment can create a much larger percentage return on that equity than the same property would produce if purchased entirely with cash.","The same mechanism works in reverse: debt service can turn an otherwise profitable property into negative annual cash flow, and a decline in property value can erase a large share of the investor's equity."]},
{heading:"Property value, down payment and loan amount",text:["If a $400,000 property is purchased with 25% down, the modeled down payment is $100,000 and the mortgage is $300,000. Reducing the down payment increases leverage and lowers the initial equity denominator used for cash-on-cash and leveraged return calculations. It also increases the mortgage balance and annual debt service. A lower down payment therefore does not automatically improve the investment; it magnifies both the financing burden and the sensitivity of equity returns.","Real acquisitions also require closing costs, reserves and sometimes renovation capital, which this model does not add to invested cash."]},
{heading:"How annual debt service is calculated",text:["The mortgage payment uses the standard fully amortizing payment formula with the entered annual interest rate converted to a monthly rate and a fixed 360-month term. Annual debt service is twelve monthly payments. The calculator does not ask for a different amortization period, interest-only phase, balloon payment, adjustable rate or lender fees, so properties financed on those terms require a separate model.","Mortgage rate has a direct effect on annual cash flow because a higher rate increases the payment even when property value, down payment and NOI remain unchanged."]},
{heading:"NOI, cap rate and cash flow are different",text:["Annual NOI is entered directly. The calculator divides NOI by property value to show cap rate, then subtracts annual mortgage debt service to estimate annual cash flow. NOI should normally represent property income after operating expenses but before financing costs, income taxes, depreciation and capital expenditures. If you enter gross rent instead of NOI, both cap rate and cash flow will be overstated.","Cash-on-cash return is annual modeled cash flow divided by the down payment, so it can be negative when debt service exceeds NOI even if the property is expected to appreciate."]},
{heading:"Appreciation and exit value",text:["The model compounds the entered appreciation rate annually for the selected holding period. A $400,000 property appreciating at 3% for ten years is modeled at about $537,600 before selling costs. Appreciation is uncertain and local: supply, rents, interest rates, employment, zoning, property condition and neighborhood changes can all affect future value. A single constant rate is useful for scenario analysis but should not be treated as a forecast.","Run flat, conservative and stronger appreciation cases because leverage makes the equity outcome particularly sensitive to the eventual sale price."]},
{heading:"Mortgage amortization builds equity",text:["At exit, the calculator estimates the remaining mortgage balance after the selected number of monthly payments. Early in a 30-year mortgage, a larger portion of each payment is interest; later, more goes to principal. Equity at exit is modeled property value minus the remaining loan balance. This means equity can grow from both appreciation and principal amortization, even when annual cash flow is modest.","The model assumes all scheduled payments are made and does not include refinancing, extra principal payments, delinquency or changes in the loan terms."]},
{heading:"Worked leveraged-property example",text:["Consider a $400,000 property with 25% down, a $300,000 mortgage, 6.5% interest, $30,000 annual NOI, 3% appreciation and a ten-year hold. The calculator first estimates annual mortgage payments, subtracts them from NOI for annual cash flow, compounds the property value for ten years and subtracts the remaining mortgage at exit. It then compares total modeled gain with the $100,000 down payment.","Compare the same inputs with 100% down to see why leverage can increase percentage return on equity even though the financed property pays substantial interest."]},
{heading:"Leveraged ROI versus unleveraged ROI",text:["The leveraged ROI in this tool includes repeated annual cash flow plus ending equity minus the original down payment, divided by that down payment. The unleveraged comparison uses appreciation plus NOI over the holding period divided by property value. These are simplified cumulative returns, not annualized internal rates of return. Timing matters in real investments, so an IRR model that includes acquisition costs, annual cash flows, capital spending and net sale proceeds can give a more complete comparison.","The leverage multiplier simply compares the two percentage returns; it is not a measure of safety."]},
{heading:"Costs missing from the simplified model",text:["The calculation can look attractive if important ownership costs are omitted from NOI. Vacancy, management, repairs, property taxes, insurance, utilities paid by the owner, HOA charges and routine maintenance should already be reflected when estimating NOI. Large capital expenditures, acquisition costs, loan points, refinancing costs and selling commissions are not separately modeled. Income taxes and depreciation are also outside this calculator.","For a purchase decision, build a property-specific cash-flow model and use this tool as a leverage sensitivity check rather than the only underwriting analysis."]},
{heading:"Stress-testing leverage before buying",text:["A useful stress test combines weaker rent or higher expenses with little appreciation and a higher financing rate. Ask whether the property can still cover debt service and whether you could fund negative cash flow without a forced sale. Also test a lower exit value because leverage leaves the lender's claim ahead of the investor's equity. If the strategy works only with aggressive appreciation assumptions, the apparent return may be compensation for substantial risk rather than a free benefit from borrowing.","Debt-service coverage, reserves, loan covenants and local market liquidity belong alongside the calculator's ROI output."]},
]},
"superhero-name":{title:'Superhero Name Generator',sections:[
{heading:'How superhero names work',text:['Memorable superhero names usually communicate one or two ideas quickly: power, origin, visual identity, personality or role.', 'A generator can combine motifs such as speed, shadow, metal, weather or cosmic imagery, but the strongest names still sound pronounceable and distinct.']},
{heading:'Match the name to the character',text:['A street-level detective, cosmic guardian and comedic sidekick should not all use the same naming vocabulary.', 'Start from the character’s abilities, tone, setting and public persona. A deliberately ironic name can work, but it should feel intentional.']},
{heading:'Sound and rhythm',text:['Alliteration, stressed syllables and compact word shapes can make a name easier to remember.', 'Read generated names aloud; awkward consonant clusters or accidental rhymes may look acceptable on screen but sound clumsy in dialogue.']},
{heading:'Avoid accidental copying',text:['A generated name can resemble an existing comic, game or film character by chance.', 'Search important names before publishing or commercializing a project, especially when the name is distinctive enough to function as a brand.']},
{heading:'Secret identity versus title',text:['Some heroes use a codename chosen by the character, while others receive a public nickname or inherit a mantle.', 'Thinking about who coined the name can make it fit the story better than simply selecting the most dramatic phrase.']},
{heading:'Iterate instead of accepting the first result',text:['Use generated names as candidates.', 'Keep the useful noun, adjective, rhythm or theme, then remix it until the name fits the character’s world. The generator is most useful as an ideation tool rather than an authority on the final choice.']},
]},
"college-financial-aid-strategies-calculator":{title:'College Financial Aid Strategies Calculator',sections:[
{heading:'Separate sticker price from net price',text:['Published tuition and cost of attendance are not the same as the family’s expected net cost.', 'Grants and scholarships reduce price without repayment, while loans and work-study are forms of financing. Compare schools on net price and four-year affordability rather than headline tuition alone.']},
{heading:'FAFSA inputs and the Student Aid Index',text:['Federal aid eligibility uses FAFSA information to calculate the Student Aid Index under current rules.', 'Income, certain assets, household circumstances and school cost interact in ways a simple calculator can only approximate. The SAI is not a bill and can be negative.']},
{heading:'Assets are not all treated alike',text:['Parent assets, student assets, retirement accounts, home equity and business interests can receive different treatment depending on the aid methodology and institution.', 'CSS Profile schools may ask for information that FAFSA does not.']},
{heading:'Timing can affect aid-year data',text:['FAFSA uses specified tax-year information, so income changes, one-time gains and unusual circumstances may not line up with the family’s current ability to pay.', 'Financial-aid offices can sometimes review documented special circumstances through professional judgment.']},
{heading:'Merit aid and need aid are different',text:['Merit scholarships may depend on academics, talent or institutional recruiting goals rather than demonstrated financial need.', 'A strategy should evaluate renewal conditions, GPA requirements and whether an award is guaranteed for later years.']},
{heading:'Borrowing belongs in the comparison',text:['Federal student loans, parent loans and private loans have different rates, protections and repayment terms.', 'A lower first-year net price can still lead to a worse four-year outcome if later aid falls or borrowing rises. Model the entire degree path and verify current program rules with each school.']},
]},
"opportunity-zone-calculator":{title:'Opportunity Zone Calculator',sections:[
{heading:'What a Qualified Opportunity Fund changes',text:['A Qualified Opportunity Fund invests in qualifying Opportunity Zone property under federal tax rules.', 'The investment thesis should be separated from the tax treatment: a weak project does not become attractive merely because it sits inside a tax-advantaged structure.']},
{heading:'Eligible gain and investment timing',text:['Opportunity Zone deferral rules historically focused on investing eligible capital gain within prescribed periods.', 'Legislative changes have altered the practical value of older deferral benefits, so the calculator must state the tax year and rule set it assumes rather than presenting permanent universal rules.']},
{heading:'Ten-year holding concept',text:['A major feature of the regime is potential favorable treatment of appreciation in a qualifying QOF investment after a sufficiently long holding period, subject to statutory requirements.', 'The benefit relates to qualifying investment appreciation; it does not erase unrelated taxes, fees or operating risk.']},
{heading:'Model the underlying economics',text:['Project cash flows should include purchase or development cost, financing, operating income, vacancies, expenses, sale assumptions and fund-level fees.', 'Compare after-tax outcomes with a realistic non-QOZ alternative using the same risk and holding period.']},
{heading:'Compliance risk is real',text:['QOF qualification, testing dates, improvement requirements, entity structure and reporting can affect tax treatment.', 'A calculator cannot verify that a particular fund or project satisfies every requirement.']},
{heading:'Liquidity and concentration',text:['Opportunity Zone investments can be illiquid and concentrated in a single project, sponsor or geography.', 'The long holding period that supports a tax benefit can also make exit difficult. Review offering documents, sponsor incentives and current tax guidance before investing.']},
]},
"leveraged-etf-decay-calculator":{title:'Leveraged ETF Decay Calculator',sections:[
{heading:'Daily leverage is the key',text:['Most leveraged ETFs target a multiple of an index’s DAILY return, not a multiple of the index’s long-term return.', 'The fund resets exposure each trading day. Over multiple days, compounding makes the ending result depend on the path of returns.']},
{heading:'Why volatility drag appears',text:['Suppose an index rises 10% and then falls 9.09%; it returns to its starting value.', 'A 2x daily product would rise about 20% and then fall about 18.18%, ending below its start. The loss comes from multiplying percentage changes from a changed base, not from a mysterious separate fee.']},
{heading:'Trend can help or hurt',text:['In a persistent trend, daily compounding can sometimes produce a multi-day return greater than the simple leverage multiple.', 'In choppy markets, repeated reversals can erode value. Therefore “decay” is not a fixed daily charge that can be projected independently of the return path.']},
{heading:'Inverse leveraged ETFs behave similarly',text:['Inverse funds target negative daily exposure and also reset daily.', 'A -2x product is not guaranteed to deliver exactly twice the opposite of an index over weeks or months.']},
{heading:'Fees and financing are additional',text:['Expense ratios, derivatives financing, trading costs and tracking differences can reduce returns beyond pure volatility effects.', 'A clean calculator should distinguish path-dependent compounding from explicit costs.']},
{heading:'Use scenarios, not a single annual return',text:['To evaluate holding risk, test sequences with the same average return but different volatility.', 'The calculator is most informative when it shows how daily moves compound rather than extrapolating one annual index return into a guaranteed leveraged outcome.']},
]},
"disability-insurance-calculator":{title:'Disability Insurance Calculator',sections:[
{heading:'Replace income, not gross salary blindly',text:['Disability coverage is designed to replace part of earnings when illness or injury prevents work.', 'Benefits are often limited to a percentage of income, so a needs estimate should start with essential spending, existing benefits and the income gap rather than assuming 100% salary replacement.']},
{heading:'Definition of disability matters',text:['Policies can define disability using own-occupation, any-occupation or modified standards.', 'A surgeon unable to perform surgery may be treated differently under an own-occupation contract than under a stricter any-occupation definition. The monthly benefit alone does not describe the protection.']},
{heading:'Elimination and benefit periods',text:['The elimination period is the waiting time before benefits begin.', 'Longer waits can reduce premium but require more emergency savings. The benefit period determines how long qualifying payments can continue, such as two years, five years or to a specified age.']},
{heading:'Employer coverage may be incomplete',text:['Group long-term disability can be valuable but may have benefit caps, taxable benefits, limited portability or narrower definitions.', 'If the employer pays the premium, tax treatment of benefits may differ from personally paid coverage under applicable rules.']},
{heading:'Residual and partial disability',text:['Some policies pay when a disability reduces earnings without preventing all work.', 'Residual-benefit formulas, recovery benefits and return-to-work provisions can be important for occupations where capacity can decline gradually.']},
{heading:'Read exclusions and riders',text:['Pre-existing-condition rules, mental/nervous limitations, substance exclusions, cost-of-living riders, future-purchase options and non-cancelable/guaranteed-renewable terms can materially change value.', 'Use the calculator to size a gap, then compare actual policy contracts rather than premiums alone.']},
]},
"vitamin-d-status-calculator":{title:"Vitamin D Status Calculator",sections:[
{heading:"What this calculator estimates—and what it cannot measure",text:["This tool estimates a vitamin D status from modeled daily vitamin D input rather than measuring vitamin D in blood. It converts dietary micrograms to IU, adds supplements and an estimate of skin synthesis from sun exposure, then divides total modeled IU by 50 to produce an estimated ng/mL value. That is a simplified educational relationship, not a validated replacement for a serum 25-hydroxyvitamin D test.","Two people with the same sun and supplement inputs can have different blood levels because absorption, genetics, body composition, medications, liver or kidney disease and many other factors affect vitamin D metabolism."]},
{heading:"Sun exposure is difficult to convert into IU",text:["The calculator starts with minutes of daily sun exposure and multiplies them by skin-tone, season, latitude and age factors. In real life, UVB exposure also depends on time of day, cloud cover, altitude, clothing, sunscreen, how much skin is exposed and local UV index. Sitting near a closed window is not equivalent to direct UVB exposure because ordinary glass blocks much of the UVB responsible for cutaneous vitamin D production.","Use the sun estimate as a scenario input, not as a prescription to increase unprotected sun exposure."]},
{heading:"Why skin tone affects the model",text:["The model uses factors of 1.0 for light, 0.6 for medium and 0.3 for dark skin. Melanin absorbs ultraviolet radiation, so darker skin generally requires more UVB exposure to produce the same amount of vitamin D under otherwise similar conditions. However, three broad categories cannot capture the full range of pigmentation, behavior or individual response.","The skin-tone input therefore changes the calculator's estimated sun contribution, but it should not be interpreted as a precise biological conversion for a specific person."]},
{heading:"Latitude and season can sharply change UVB availability",text:["The code reduces the sun contribution in winter and at higher latitudes. This reflects the general principle that the solar angle can reduce UVB reaching the surface, especially during winter at northern or southern latitudes. The model uses broad thresholds rather than the user's exact location, date, UV index or weather.","A person who receives substantial summer sun can still have a different winter status, which is why the calculator flags winter at latitude above 40° as higher risk."]},
{heading:"BMI and age adjustments",text:["The implemented formula reduces the estimated contribution when BMI exceeds 25 and again when it exceeds 30, and it reduces the age factor after age 50 and more after age 70. Higher body fat is associated with lower circulating vitamin D concentrations in many populations, and older skin has less capacity for cutaneous vitamin D synthesis. These are population-level relationships, not proof of deficiency in an individual.","Do not use the model to choose a high-dose regimen solely because age or BMI lowers the estimate."]},
{heading:"Dietary vitamin D and unit conversion",text:["The dietary input is entered in micrograms and multiplied by 40 because 1 microgram of vitamin D equals 40 IU. Food sources can include fatty fish, egg yolks and fortified foods, depending on the diet and country. Nutrition labels and serving sizes are more reliable than guessing. For example, 10 micrograms of dietary vitamin D contributes 400 IU in the calculator.","Diet is added to supplements and estimated sun synthesis to produce the displayed total daily IU."]},
{heading:"How supplements affect the displayed estimate",text:["Supplement IU is added directly to the model, so it can dominate the estimated result when sun synthesis is low. The calculator then recommends 4,000 IU when its estimated level is below 30 ng/mL, 2,000 IU below 50, and 1,000 IU otherwise. Those outputs are hard-coded educational suggestions, not individualized dosing advice. Appropriate supplementation can depend on measured 25-OH-D, calcium status, kidney function, pregnancy, medications and clinician guidance.","More vitamin D is not automatically better, and excessive chronic intake can cause toxicity and hypercalcemia."]},
{heading:"Understanding ng/mL and the status bands",text:["The displayed categories are based on the calculator's own thresholds: below 10 ng/mL severely deficient, 10–20 deficient, 20–30 insufficient, 30–50 sufficient and 50–80 optimal. Professional organizations do not all use identical cutoffs or agree that higher levels within this range provide additional benefit. A laboratory result should be interpreted using the laboratory reference range and relevant clinical guidance.","The calculator's gauge is therefore best viewed as an educational visualization of its internal model rather than a clinical diagnosis."]},
{heading:"Worked vitamin D scenario",text:["Suppose a 42-year-old with medium skin tone at 40° latitude enters 15 minutes of winter sun, BMI 25, a 1,000 IU supplement and 2 micrograms from diet. Winter and latitude substantially reduce the modeled sun synthesis, diet adds 80 IU, and the supplement supplies most of the modeled intake. Changing only the season to summer produces a much larger sun contribution even though every other input is unchanged.","That comparison demonstrates how strongly the model depends on its seasonal assumptions; it does not prove the person's blood concentration will change by the same amount."]},
{heading:"When a blood test matters",text:["The calculator flags testing when its estimate is low or age is above 60, but testing decisions should be based on clinical context. A serum 25-hydroxyvitamin D test directly measures the biomarker used to assess vitamin D status and is far more informative than estimating exposure. People with symptoms, malabsorption, osteoporosis, kidney or liver disease, certain medications or treatment for a known deficiency may need clinician-directed testing and follow-up.","Use this tool to understand factors that influence vitamin D, not to replace laboratory measurement or medical care."]},
]},
"alimony-tax-calculator":{title:"Alimony Tax Calculator",sections:[
{heading:"The federal tax rule this calculator models",text:["The calculator separates agreements by whether the divorce or separation instrument was finalized before 2019. For older qualifying instruments, it models the historical federal rule under which deductible alimony reduced the payer's taxable income and qualifying alimony was taxable to the recipient. For post-2018 instruments, it models the Tax Cuts and Jobs Act treatment: no federal deduction for the payer and no federal taxable income to the recipient.","This date split is central to the calculation, but the legal terms of the actual instrument still determine whether a payment qualifies and which regime applies."]},
{heading:"How payer net cost is calculated",text:["For a pre-2019 scenario, the tool multiplies annual alimony by the payer's entered marginal tax rate to estimate the tax value of the deduction. It subtracts that amount from the cash payment to show a modeled payer net cost. A $30,000 payment at a 32% entered rate therefore creates a $9,600 modeled tax effect and a $20,400 modeled net cost. For a post-2018 scenario, the deduction is zero and net cost equals the full payment.","This is a marginal-rate illustration; it does not recalculate an actual federal return."]},
{heading:"How recipient net income is modeled",text:["Under the pre-2019 branch, annual alimony is multiplied by the recipient's entered marginal rate to estimate tax attributable to the payment. The result is subtracted from the amount received. Under the post-2018 branch, the calculator assigns zero federal income tax to the alimony itself and shows the full payment as net received.","The recipient may still owe tax on wages, investments or other income. The output isolates the modeled treatment of the alimony payment rather than estimating the recipient's complete tax liability."]},
{heading:"Why marginal tax rates matter",text:["The entered percentages are used directly, so the result is sensitive to them. A marginal bracket is not the same as an effective tax rate, and a deduction can interact with taxable income, filing status and other provisions. Likewise, adding taxable alimony under the historical rules could move part of a recipient's income into another bracket. The calculator does not perform those bracket-by-bracket computations.","For historical planning or return analysis, use actual taxable-income calculations instead of assuming one flat percentage applies to the entire payment."]},
{heading:"Modified pre-2019 agreements require special attention",text:["A divorce instrument executed before 2019 can have different treatment after modification if the modification expressly provides that the post-2018 rules apply. The calculator asks only for a year and cannot read the modification language. Entering 2018 therefore does not prove that the old deduction/taxable-income regime still applies today.","Review the decree, separation agreement and later modifications before relying on the date branch, particularly when the agreement has been renegotiated since the original divorce."]},
{heading:"Alimony is not child support or a property settlement",text:["Federal tax rules distinguish qualifying alimony from child support and transfers of property incident to divorce. The calculator assumes the entered annual amount is alimony subject to the selected regime. It does not test requirements that historically applied to deductible alimony, identify payments that terminate on death, separate child-related reductions, or classify a transfer of property.","If the legal character of a payment is uncertain, that question must be resolved before a tax calculation based on alimony rules is meaningful."]},
{heading:"Worked comparison across the 2019 rule change",text:["Assume $36,000 annual alimony, a 32% payer rate and a 22% recipient rate. Under the calculator's pre-2019 branch, payer tax savings are $11,520, modeled payer net cost is $24,480, recipient tax is $7,920 and recipient net receipt is $28,080. Under the post-2018 branch, payer net cost is $36,000 and recipient net receipt is $36,000 because the calculator assigns neither deduction nor taxable alimony income.","The example shows how the same cash transfer can have very different modeled federal consequences depending on the governing instrument."]},
{heading:"State tax treatment can differ",text:["This calculator is explicitly a simplified federal model. State income-tax treatment may not mirror federal law, and residency can change during a multi-year support arrangement. A state may have its own conformity rules, deductions, additions or filing requirements. The calculator also ignores local income taxes.","When comparing settlement terms, model federal and applicable state consequences separately so a zero federal tax effect is not mistaken for a zero total tax effect."]},
{heading:"Cash-flow planning for payer and recipient",text:["Tax treatment is only one part of support planning. The payer needs to budget the actual payment schedule, while the recipient needs to distinguish gross support from spendable cash after any applicable taxes. Under the historical regime, withholding was not automatically embedded in the payment, so recipients could need estimated-tax planning. Under the current federal regime, the alimony itself generally does not create recipient taxable income for covered instruments.","Use annual figures for comparison, then convert them to the actual monthly or other payment schedule in the agreement."]},
{heading:"Limits of this calculator",text:["PayerIncome and recipientIncome are accepted by the calculation function but are not used in the current formula, and the visible interface does not ask for them. The model also ignores filing status, deductions, credits, AMT, state taxes, recapture rules, arrears, lump-sum settlements and changes in support during the year. It should therefore be treated as a transparent illustration of the old-versus-new federal rule rather than a tax return calculator.","For a real divorce agreement or modification, confirm the legal classification and tax treatment with current primary guidance and qualified advisers."]},
]},
"pain-score-calculator":{title:'Pain Score Calculator',sections:[
{heading:'Pain scores describe experience, not tissue damage',text:['A numeric pain rating summarizes how intense pain feels to the person reporting it.', 'It does not directly measure injury severity, inflammation or structural damage. Two people with similar conditions can report different numbers, and the same person’s score can vary with sleep, stress, activity and context.']},
{heading:'Intensity is only one dimension',text:['Frequency, duration, interference with walking or work, sleep disruption and ability to perform normal activities can be as important as the 0–10 intensity number.', 'A useful calculator should keep these dimensions visible rather than collapsing everything into one unexplained total.']},
{heading:'Track change using the same scale',text:['Pain scores are most useful longitudinally when the same person uses the same scale under similar conditions.', 'A change from 8 to 5 may be meaningful even though the scale is subjective. Record medication timing and activity when comparing days.']},
{heading:'Acute and chronic pain differ',text:['Acute pain often accompanies recent injury or illness, while chronic pain can persist beyond expected tissue healing and involve nervous-system sensitization, mood, sleep and function.', 'A single scoring formula cannot determine the cause.']},
{heading:'Medication use needs context',text:['Analgesics can change reported pain and function, but more medication is not automatically better.', 'Side effects, tolerance and medication-specific risks matter. The calculator should not recommend dose changes.']},
{heading:'Urgent symptoms override the score',text:['Severe pain with chest pressure, difficulty breathing, new weakness, loss of bladder/bowel control, major trauma, high fever or other alarming symptoms needs prompt assessment regardless of the numeric score.', 'Use the result as a communication aid, not a diagnostic endpoint.']},
]},
"estate-liquidity-calculator":{title:"Estate Liquidity Calculator",sections:[
{heading:"What estate liquidity means",text:["An estate can be wealthy on paper and still lack enough cash to pay obligations when they come due. Real estate, closely held businesses, farms, collectibles and concentrated private investments may represent substantial value but cannot always be converted to cash quickly or without a discount. This calculator compares entered liquid assets with estimated federal estate tax, state estate tax and administration costs to identify a potential liquidity gap.","The goal is not to calculate net worth; it is to ask whether cash and readily marketable assets are sufficient to meet near-term estate obligations without a forced sale."]},
{heading:"How total obligations are calculated",text:["The underlying function adds federal estate tax, state tax, debts and administration costs. On the current page, however, the debts argument is always passed as zero even though the interface labels one field 'Debts & Expenses.' That visible field is actually sent as administration costs. Users should therefore understand that the present UI does not separately model mortgages, personal loans, business debt or other creditor claims.","A comprehensive estate liquidity analysis should list each material obligation and its expected due date rather than relying on one combined estimate."]},
{heading:"Liquid assets versus illiquid estate value",text:["Liquid assets generally include cash and assets that can realistically be converted to cash in the required timeframe without materially disrupting the estate plan. Publicly traded securities may be relatively liquid; a family business, rental property or undeveloped land may not be. Gross estate value is displayed for context but is not used to reduce the liquidity gap in the current formula.","That design is intentional from a liquidity perspective: owning a valuable building does not itself pay a tax bill unless the estate can sell it, borrow against it or otherwise generate cash."]},
{heading:"The liquidity-gap formula",text:["Liquidity gap equals the greater of zero or total modeled obligations minus liquid assets. If obligations are $1.1 million and liquid assets are $650,000, the gap is $450,000. If liquid assets exceed obligations, the gap is zero and the calculator marks forced-sale risk as false. The result is a funding shortfall under the entered assumptions, not proof that a sale will occur.","Executors may have access to other sources of cash, payment extensions, borrowing, asset income or planning structures that are outside this simple calculation."]},
{heading:"Why estate-tax estimates must be calculated separately",text:["The calculator asks the user to enter federal and state estate tax rather than calculating those taxes from gross estate value. That matters because taxable estate calculations can involve deductions, marital transfers, charitable transfers, prior taxable gifts, exemption amounts, portability, state-specific thresholds and other rules. Gross estate value alone is not enough to determine tax liability.","Use an appropriate estate-tax analysis first, then bring the resulting estimated cash liability into this liquidity model."]},
{heading:"Administration costs and timing",text:["Probate and estate administration can create attorney, accounting, appraisal, executor, court, property-maintenance and transaction costs. Some expenses arise quickly while others develop over months or years. The calculator combines them into one amount and does not model timing. A realistic liquidity plan should distinguish immediate cash needs from later obligations because the estate may receive income, sell assets deliberately or obtain financing during administration.","Add a contingency reserve when costs are uncertain rather than assuming the first estimate will be exact."]},
{heading:"Life-insurance-needed output is only a gap proxy",text:["The function sets 'life insurance needed' equal to the calculated liquidity gap. That does not mean life insurance is automatically the best solution or that the displayed amount is an appropriate death benefit. Existing coverage, ownership, beneficiary structure, insurability, premium cost, estate inclusion and broader family goals all matter. The estimated annual premium is simply 0.4% of the gap, a rough modeling assumption rather than an insurer quote.","Treat these outputs as prompts for planning, not product recommendations."]},
{heading:"Closely held businesses and IRC Section 6166",text:["The calculator mentions IRC Section 6166 when federal estate tax is entered. In qualifying estates with a sufficiently large closely held business interest, federal law may allow part of the estate tax attributable to that business to be paid in installments rather than entirely at the ordinary due date. Eligibility and computation are technical and depend on the estate's facts.","A possible deferral can reduce immediate liquidity pressure, but the calculator does not test eligibility, calculate the deferred portion, interest or payment schedule."]},
{heading:"Worked estate-liquidity example",text:["Suppose an estate is worth $6 million but holds only $500,000 of liquid assets. The executor estimates $650,000 federal estate tax, $150,000 state estate tax and $100,000 administration costs. The calculator totals $900,000 of obligations and reports a $400,000 gap. The key lesson is that the estate's $6 million gross value does not eliminate the shortfall if most of that value is tied up in assets that cannot provide cash when needed.","Planning can then focus specifically on how that $400,000 timing gap might be funded."]},
{heading:"Building a more complete liquidity plan",text:["For serious estate planning, create an asset-by-asset liquidity schedule. Identify cash, marketable securities, insurance proceeds, expected business distributions and assets that could be sold or borrowed against. Match those resources with taxes, debts, administration costs, family support needs and other obligations by expected date. Stress-test lower sale prices and longer transaction timelines for illiquid property.","This calculator is most useful as the first shortfall screen. Legal, tax and insurance professionals can then evaluate ownership structures, trusts, borrowing arrangements, insurance and statutory payment options in the context of the actual estate."]},
]},
"tip-calculator":{title:'Tip Calculator',sections:[
{heading:'The basic tip formula',text:['A tip is usually calculated as bill amount multiplied by the selected tip percentage.', 'A $80 eligible bill at 20% produces a $16 tip and a $96 total before any other adjustments. For a split bill, divide the final total by the number of people unless different diners are paying different shares.']},
{heading:'Pre-tax or post-tax tipping',text:['Customs vary on whether the percentage is applied to the pre-tax subtotal or the final amount including sales tax.', 'A calculator should make the chosen base clear. Using the post-tax total produces a slightly larger tip when tax is present.']},
{heading:'Check for automatic gratuity',text:['Restaurants may add a service charge or automatic gratuity, especially for larger groups.', 'Review the receipt before adding another full tip. A service charge is not always distributed to staff in the same way as a voluntary gratuity, and local rules vary.']},
{heading:'Discounts and coupons',text:['When a meal is discounted, some diners choose to tip on the pre-discount value because the service effort did not fall with the coupon.', 'If the calculator uses the amount actually paid, manually adjust the tipping base when that is your preference.']},
{heading:'Splitting fairly',text:['Equal division is convenient when orders are similar.', 'If one diner ordered substantially more, calculate individual subtotals or use weighted shares. The tip itself can be allocated in the same proportions as the underlying bill.']},
{heading:'Rounding without losing track',text:['Rounding the tip or per-person total can make payment easier.', 'Decide whether rounding changes the tip percentage or merely the cash amount. The calculator should show the unrounded result first so the effect is transparent.']},
]},
"json-schema-gen":{title:'JSON Schema Generator',sections:[
{heading:'Inference starts from observed JSON',text:['A schema generator can inspect a sample JSON value and infer types such as object, array, string, number, integer, boolean or null.', 'The result describes the sample; it does not prove that future payloads always follow the same shape.']},
{heading:'Required properties need intent',text:['If a property appears in one sample, automatically marking it required may be too strict.', 'Real APIs often omit optional fields. Generate an initial schema, then decide required fields from the contract rather than presence in a single example.']},
{heading:'Arrays need multiple examples',text:['An array containing one object provides weak evidence about all allowed items.', 'Mixed arrays may require anyOf/oneOf or a broader item schema. Empty arrays reveal almost nothing about item type.']},
{heading:'Null is different from missing',text:['A property whose value is null is present with a null value; an absent property is missing.', 'JSON Schema can model these separately. Do not infer optionality simply because a sample contains null.']},
{heading:'Constraints go beyond type',text:['Production schemas may need minimum/maximum, string patterns, formats, enum values, array uniqueness, additionalProperties rules and nested references.', 'These constraints usually require domain knowledge and cannot be safely invented from one payload.']},
{heading:'Choose the schema draft deliberately',text:['JSON Schema drafts differ in vocabulary and behavior.', '`$schema`, `$id`, `$defs`, references and newer keywords should match the validator ecosystem you actually use. Always validate generated schemas against representative valid and invalid examples before treating them as an API contract.']},
]},
"hydration-exercise-calculator":{title:'Exercise Hydration Calculator',sections:[
{heading:'Estimate sweat loss from body mass',text:['A practical sweat-rate estimate compares pre- and post-exercise body mass while accounting for fluid consumed and urine produced.', 'Roughly, one kilogram of acute body-mass loss corresponds to about one liter of water, though measurement noise and clothing can affect the estimate.']},
{heading:'Duration converts loss to sweat rate',text:['Divide estimated fluid loss by exercise hours to obtain liters per hour.', 'This personal rate is more useful than a universal drinking target because sweat varies with heat, humidity, intensity, clothing, acclimatization and body size.']},
{heading:'Avoid both dehydration and overdrinking',text:['Replacing some exercise fluid loss can support performance, but drinking faster than losses can be dangerous because it may dilute blood sodium.', 'The goal during long events is not necessarily to finish at exactly the starting body weight.']},
{heading:'Sodium matters during prolonged sweating',text:['Sweat contains sodium, with large individual variation.', 'Long-duration exercise, heavy sweaters and salty sweaters may need sodium as well as water. A calculator using a fixed sodium value is only an estimate; measured sweat testing can refine it for endurance athletes.']},
{heading:'Post-exercise replacement can exceed measured loss',text:['When rapid recovery is needed, post-exercise plans sometimes target more than 100% of remaining fluid deficit because urine losses continue.', 'Food and sodium help retain fluid. The appropriate amount depends on recovery time and medical context.']},
{heading:'Know the warning signs',text:['Dizziness, confusion, collapse, severe headache, vomiting or worsening symptoms during heat exposure require attention.', 'Similar symptoms can occur with dehydration, heat illness or exercise-associated hyponatremia, so a calculator cannot safely diagnose the cause from fluid numbers alone.']},
]},
"social-security-couples-optimizer":{title:'Social Security Couples Optimizer',sections:[
{heading:'Optimize two benefit records, not one',text:['A couple’s claiming decision combines each spouse’s retirement benefit, possible spousal benefits and survivor protection.', 'The highest immediate household payment is not always the strategy with the highest lifetime or survivor value.']},
{heading:'Full retirement age anchors the comparison',text:['Claiming a retirement benefit before full retirement age generally reduces the worker benefit, while delaying beyond full retirement age can earn delayed retirement credits up to age 70.', 'The exact percentages depend on birth year and current Social Security rules.']},
{heading:'Spousal benefits have their own rules',text:['A spouse may qualify for a benefit based on the other worker’s record, but the maximum spousal amount is tied to the worker’s primary insurance amount rather than the worker’s delayed age-70 benefit.', 'Deemed-filing rules can limit the ability to choose only one benefit type.']},
{heading:'Survivor benefits change the household risk',text:['When one spouse dies, the surviving spouse generally does not keep both full checks.', 'Survivor rules can make delaying the higher earner’s benefit valuable because that larger record may support the surviving spouse later.']},
{heading:'Longevity and cash-flow needs drive tradeoffs',text:['Early claiming produces more checks sooner; delayed claiming produces fewer early checks but a larger monthly amount later.', 'Compare cumulative benefits under several longevity assumptions and include the household’s need for current income rather than relying on one break-even age.']},
{heading:'Taxes and Medicare can alter net income',text:['Social Security benefits can become taxable depending on other income, and Medicare premiums can be affected by income-related surcharges.', 'A gross-benefit optimizer does not automatically calculate these interactions. Verify estimates with current SSA records and rules before filing.']},
]},
}
Object.assign(guides, {
"immune-strength-calculator": {title:"Immune Strength Calculator", sections:[
{heading:"What this score can and cannot tell you",text:["An immune-strength score is best understood as a lifestyle-oriented screening summary, not a measurement of the immune system itself. Immune function involves innate and adaptive responses, white blood cells, antibodies, barriers, inflammation, vaccination history, age, medications, chronic conditions and recent infections. A short questionnaire cannot compress all of those mechanisms into a clinically validated percentage. The useful role of this calculator is narrower: it can organize modifiable habits that commonly influence recovery and general health and show where the entered pattern looks stronger or weaker.","Do not interpret a high score as proof that you cannot become infected, and do not interpret a low score as a diagnosis of immune deficiency. Recurrent or unusually severe infections, persistent fever, unexplained weight loss, or concerns related to immunosuppressive medicines require professional evaluation rather than a lifestyle score." ]},
{heading:"Sleep and immune recovery",text:["Sleep is one of the most important contextual inputs because immune signaling and recovery are linked with sleep duration, regularity and quality. A person reporting seven or eight hours may still have poor recovery if sleep is fragmented, shift work constantly changes the schedule, or untreated sleep problems are present. Conversely, one short night does not mean the immune system suddenly became weak. The calculator should therefore be read as a pattern indicator rather than a day-to-day laboratory measure.","When using the result for self-improvement, compare several weeks of typical sleep rather than entering an unusually good or bad night. If the score improves after a more consistent schedule, that reflects a healthier input pattern; it does not prove a quantified increase in immune-cell activity." ]},
{heading:"Nutrition, protein and micronutrient context",text:["Adequate energy, protein and micronutrients support normal immune processes, but more is not always better. Vitamin C, vitamin D, zinc, iron, selenium, folate and vitamin B12 all have biological roles, yet supplementation above need does not automatically create stronger immunity and some nutrients can be harmful in excess. A food pattern containing vegetables, fruit, legumes, whole grains, protein sources and appropriate fats gives the calculator a more meaningful foundation than focusing on one so-called immune-boosting food.","Dietary restrictions, malabsorption, pregnancy, older age and certain medications can change nutrient needs. If the tool asks broad diet questions, treat them as proxies for diet quality rather than evidence that a specific deficiency exists. Laboratory testing and clinical history are needed when deficiency is a real concern." ]},
{heading:"Exercise: enough stimulus without confusing exhaustion with fitness",text:["Regular moderate physical activity is generally compatible with good health and immune regulation, while very high training loads combined with inadequate sleep, calories or recovery can leave an athlete feeling run down. The important distinction is training load relative to recovery capacity. Two people completing the same weekly exercise can have very different stress because of conditioning, work demands, illness and nutrition.","Use a typical training week when entering exercise information. If you are acutely ill, the calculator is not a return-to-play decision tool. Symptoms such as chest pain, breathing difficulty, fainting or a significant fever should not be reduced to a score." ]},
{heading:"Stress, smoking, alcohol and other modifiers",text:["Chronic psychological stress can influence sleep, appetite, inflammation and health behaviors, so a stress input often affects several pathways at once. Smoking adds direct respiratory and cardiovascular harms and can impair host defenses. Heavy alcohol use can also affect sleep, nutrition, liver function and immune responses. These inputs deserve more weight in interpretation than tiny differences between two otherwise healthy diet choices.","A useful way to read the result is to identify the largest modifiable weakness rather than trying to maximize every category. Stopping smoking, improving persistently short sleep or addressing heavy alcohol use is generally more consequential than chasing a perfect score through minor optimizations." ]},
{heading:"Age, medical history and medications",text:["Immune responses change with age, and many conditions or treatments can alter infection risk independently of lifestyle. Corticosteroids, chemotherapy, transplant medicines and some biologic therapies are examples where a general wellness calculator cannot represent the real level of immunosuppression. Diabetes, kidney disease and other chronic illnesses can also change risk.","For that reason, never compare scores between people as if the higher number identifies the person with the stronger immune system. The score is most defensible as an intra-personal lifestyle checklist: compare your own inputs over time while keeping its medical limitations explicit." ]},
{heading:"Worked interpretation example",text:["Suppose a user exercises regularly and eats a varied diet but sleeps about five hours, reports high ongoing stress and smokes. A middling result should not lead to five equally weighted recommendations. The dominant opportunities are the short sleep, smoking and unmanaged stress. Improving those factors may also make exercise recovery and food choices easier, creating benefits that the simple score cannot model.","Now consider a second user with consistent sleep, no smoking, moderate exercise and a balanced diet who receives a strong score. The correct interpretation is that the entered lifestyle pattern contains fewer obvious risk flags. It is not a prediction that the person will avoid influenza, COVID-19 or another infection, because exposure, vaccination, prior immunity and individual biology are outside the calculation." ]},
{heading:"How to use the calculator responsibly",text:["Re-run the tool when a meaningful habit changes and keep the inputs consistent enough that comparisons are fair. Look for direction over time rather than reacting to a one-point movement. If the calculator exposes category subscores, those are often more actionable than the headline number because they show which behavior caused the change.","The best outcome is not a perfect immune-strength score. It is a realistic plan built around sleep, nutrition, movement, vaccination and preventive care appropriate to the individual. Use the calculator as an educational organizer, not as a substitute for medical testing, diagnosis or treatment." ]}
]},
"tip-calculator": {title:"Tip Calculator", sections:[
{heading:"How a tip is calculated",text:["A basic tip calculation starts with a bill amount and multiplies it by the selected tip percentage. On a $80 eligible bill, a 20% tip is $16 and the combined total is $96. If four people split that total evenly, each person's share is $24. The arithmetic is simple, but real receipts introduce decisions about taxes, service charges, discounts, uneven orders and rounding.","Percentage inputs should be interpreted as percentages of the chosen tipping base. Twenty percent means 0.20 in the formula, not 20. If the calculator also asks for the number of people, splitting changes the amount per person but does not change the total tip unless each person is separately choosing a tip." ]},
{heading:"Pre-tax versus after-tax tipping",text:["One common question is whether the percentage should be applied before or after sales tax. Customs vary, and a calculator cannot decide etiquette for every location. Mathematically, tipping after tax produces a slightly larger amount because the tax itself becomes part of the base. If food and beverage charges are $100 and tax is $8, a 20% pre-tax tip is $20 while 20% of the $108 final subtotal is $21.60.","When comparing suggested percentages, first identify which subtotal the restaurant or payment terminal is using. Two screens can both display '20%' while producing different dollar tips if one uses the pre-tax subtotal and the other uses the after-tax amount." ]},
{heading:"Service charges and automatic gratuity",text:["A service charge, hospitality charge or automatic gratuity may already appear on the receipt. Do not blindly add another full percentage without reading what the existing charge represents. Some charges are distributed to service staff, while others may be retained or allocated differently depending on the business and local rules. The receipt wording matters.","For a large party with an 18% automatic gratuity, entering another 20% as though no gratuity exists can unintentionally create a 38% combined amount before considering tax. The calculator is most useful when you enter the amount that actually remains eligible for an additional discretionary tip." ]},
{heading:"Discounts, coupons and complimentary items",text:["If a meal is discounted, people often choose to tip on the value of the service before the discount rather than on the reduced payment amount. For example, a $100 meal reduced to $70 by a promotion yields a $14 tip at 20% of the paid amount but $20 at 20% of the original value. The calculator can handle either approach, but the user must choose the intended base.","Complimentary items create the same issue. If the goal is to recognize service associated with the full meal, include their normal value in the tipping base. If the goal is simply a percentage of the charged subtotal, exclude them. State the convention so everyone splitting the bill uses the same assumption." ]},
{heading:"Splitting a bill evenly",text:["An equal split is appropriate when the group intentionally shares costs or when individual differences are immaterial. Calculate the total bill plus tip first and divide by the number of people. This avoids rounding each person's tip independently and then discovering that the group total no longer matches the receipt.","If the $126 total including tip is split among five people, the exact share is $25.20. For cash payments, the group may intentionally round shares upward and assign any extra to the tip. For card payments, preserve cents so the combined payments reconcile to the receipt." ]},
{heading:"Unequal orders and fairer splitting",text:["Equal splitting can be unfair when one diner ordered significantly more, consumed alcohol while others did not, or joined for only part of the meal. In that case, allocate each person's items first, distribute shared items using an agreed method, then apply tax and tip consistently. A simple tip calculator may not perform item-level allocation, so its per-person figure should not be mistaken for a fairness engine.","For mixed groups, a practical method is to calculate each person's pre-tax food and drink subtotal, allocate shared dishes, and then apply the same tip rate to each eligible subtotal. This keeps the tip proportional to the service value associated with each order." ]},
{heading:"Rounding without losing track of the percentage",text:["Rounding is convenient but changes the effective tip rate. If a $47 bill produces a $9.40 tip at 20%, rounding the total from $56.40 to $57 makes the actual tip $10, or about 21.3% of the bill. That may be intentional; the important point is to understand what changed.","When using a 'round total' approach, compute the implied tip by subtracting the original bill from the rounded final total. This is especially useful when a payment terminal offers fixed dollar amounts rather than percentage buttons." ]},
{heading:"Cash, card and receipt checks",text:["Before submitting payment, confirm that the tip has not already been included and that the calculator's bill amount matches the receipt. Decimal-entry errors are easy: $54.20 entered as $542 can create a tenfold mistake. Also verify the number of people before relying on the per-person result.","A tip calculator should reduce mental arithmetic, not replace receipt review. The most reliable workflow is bill base → existing service charge → chosen additional percentage → final total → split. Keeping that sequence explicit prevents most practical tipping errors." ]}
]},
"hydration-exercise-calculator": {title:"Hydration Exercise Calculator", sections:[
{heading:"What exercise hydration planning is trying to estimate",text:["Exercise hydration planning estimates fluid needs around a workout by considering duration, sweat loss and environmental conditions. It is not a universal prescription to drink as much water as possible. Sweat rates vary widely with body size, heat acclimatization, clothing, intensity, humidity and genetics, so the most useful result is an individualized range that can be checked against body-mass change and thirst.","The goal is generally to avoid large fluid deficits without creating overhydration. Drinking far beyond sweat losses can dilute blood sodium and contribute to exercise-associated hyponatremia, a potentially serious condition. That is why a calculator should be used as a planning aid rather than a command to consume a fixed volume regardless of conditions." ]},
{heading:"Estimating sweat rate from body mass",text:["A practical field estimate compares body mass before and after exercise while accounting for fluid consumed and urine produced. Roughly, one kilogram of acute body-mass loss corresponds to about one liter of net fluid loss. If an athlete starts at 70.0 kg, finishes at 69.2 kg, drinks 0.5 L and does not urinate, estimated sweat loss is about 1.3 L over the session.","Divide estimated sweat loss by exercise hours to obtain an hourly sweat rate. If that session lasted 90 minutes, 1.3 L over 1.5 hours is about 0.87 L per hour. Repeating the measurement in different weather and training conditions is more useful than assuming one test represents the entire year." ]},
{heading:"Duration, intensity, heat and humidity",text:["Longer sessions create more opportunity for fluid loss, but sweat rate is not perfectly constant. Higher intensity and hot conditions often increase heat production and sweating, while high humidity reduces evaporative cooling efficiency. Clothing and protective equipment can further increase heat strain.","Because weather changes the result, a sweat test from a cool indoor workout should not be copied directly to a summer race. Build separate estimates for common conditions such as easy training, hard training and hot competition. The calculator's environmental inputs should be treated as modifiers to an individual baseline, not as precise physiological measurements." ]},
{heading:"Pre-exercise hydration",text:["Starting exercise reasonably hydrated is more useful than trying to correct a large deficit after the workout begins. Normal meals and beverages often provide enough fluid for routine sessions. Very clear urine all day is not a requirement, and aggressively drinking liters immediately before exercise can cause discomfort and excessive urination.","For athletes with repeated sessions, travel, heat exposure or a known tendency to begin dehydrated, planned intake before exercise may be more important. Body mass trends, urine pattern, thirst and the time available before the session provide context that a single calculator field cannot capture." ]},
{heading:"During-exercise intake",text:["For short or low-intensity sessions, drinking to thirst may be adequate for many people. As duration, heat and sweat losses rise, a more deliberate plan becomes useful. The hourly target should remain anchored to observed sweat rate and gastrointestinal tolerance rather than an arbitrary maximum.","If estimated sweat rate is 0.8 L per hour, consuming 0.5 to 0.7 L per hour may limit the deficit while avoiding the need to replace every drop in real time. Athletes should test a plan during training because race intensity, aid-station spacing and stomach tolerance can make a mathematically neat target impractical." ]},
{heading:"Electrolytes and sodium losses",text:["Sweat contains sodium as well as water, and sodium concentration differs substantially between people. Visible salt residue on clothing can suggest salty sweat but does not quantify the concentration. Longer events, heavy sweating and hot conditions make sodium replacement more relevant, especially when large volumes of plain fluid are consumed.","Electrolyte products are not interchangeable: compare sodium per serving and serving volume rather than relying on marketing labels. People with hypertension, kidney disease, heart disease or medication-related fluid restrictions need individualized medical guidance rather than generic sodium targets." ]},
{heading:"Post-exercise replacement",text:["Body-mass loss after exercise provides a practical estimate of the remaining fluid deficit. Recovery intake may need to exceed the measured deficit when rapid rehydration is required because some fluid will be lost in urine. Meals also contribute water and sodium, so the beverage amount does not have to represent the entire recovery strategy.","If there is plenty of time before the next session, normal drinking and meals may restore balance gradually. If another demanding session follows soon, a structured recovery plan becomes more important. The calculator should therefore be interpreted in the context of the recovery window." ]},
{heading:"Warning signs and limits",text:["Thirst, dry mouth and declining performance can accompany dehydration, but symptoms are nonspecific. Confusion, collapse, severe headache, repeated vomiting or altered mental status during or after prolonged exercise can indicate a medical emergency and should not be managed by repeatedly entering new values into a hydration calculator.","Likewise, weight gain during a long event can be a warning that fluid intake exceeded losses. The safest use of the tool is to combine calculated estimates with measured sweat-rate data, environmental awareness and sensible limits rather than pursuing exact replacement at all costs." ]}
]},
"migraine-risk-calculator": {title:"Migraine Risk Calculator", sections:[
{heading:"A risk screen is not a migraine diagnosis",text:["Migraine is diagnosed from a clinical history that considers headache features, duration, associated symptoms, aura and alternative causes. A calculator can summarize reported patterns or known triggers, but it cannot establish that a headache is migraine or estimate an individual's exact probability of an attack. The score is best treated as an educational risk or trigger profile.","New severe headache, sudden 'worst headache' onset, headache after significant injury, fever with neck stiffness, new neurologic weakness, confusion, seizure, or a major change in an established headache pattern warrants prompt medical assessment rather than calculator interpretation." ]},
{heading:"Frequency and headache history",text:["Past attack frequency is often more informative than a generic risk label. Record headache days and migraine days separately when possible because not every headache has the same features. A calendar can reveal whether episodes cluster around sleep disruption, menstruation, travel, missed meals or periods of high stress.","A single unusually bad month should not automatically define the long-term pattern. Compare several months and note changes in duration, disability and medication use. Increasing frequency can also matter because frequent acute-medication use may contribute to medication-overuse headache in susceptible people." ]},
{heading:"Sleep and schedule disruption",text:["Both insufficient sleep and major changes in sleep timing are commonly reported around migraine attacks. Weekend oversleeping, night shifts, jet lag and repeated late nights can make a regular schedule difficult even when average weekly sleep appears acceptable. The calculator's sleep input should therefore represent consistency as well as hours.","If sleep appears to be a strong personal association, change one practical variable at a time—such as bedtime regularity—and track headache days. That approach is more informative than assuming that every commonly listed trigger applies to every person." ]},
{heading:"Stress and the let-down pattern",text:["Stress can coincide with attacks, but some people notice headaches when stress falls after an intense period rather than at the peak itself. This 'let-down' pattern is one reason simple trigger checklists can be misleading. Stress also changes sleep, meals, caffeine use and muscle tension, so several inputs may move together.","A diary should capture context, not just a yes/no stress field. Note major work or family stress, recovery days and whether other habits changed. The purpose is to identify repeatable personal patterns rather than to blame a single emotional state for every attack." ]},
{heading:"Food, hydration and caffeine",text:["Missed meals, prolonged fasting, dehydration and changes in caffeine intake can be relevant for some people. Caffeine is especially nuanced: a modest regular amount may be tolerated or even included in some acute headache medicines, while abrupt withdrawal or excessive use can provoke headache. A calculator cannot determine the ideal caffeine dose for an individual.","Avoid unnecessarily restrictive diets based only on a generic list of migraine foods. If a specific food is suspected, look for repeated timing relationships while considering confounders. Cravings can also occur during the early phase of a migraine, which can make a food eaten before pain begins look like a trigger when it was actually part of the attack." ]},
{heading:"Hormonal patterns and other individual factors",text:["Hormonal changes can influence migraine patterns, particularly around menstruation, pregnancy transitions or menopause. These relationships are individual and can interact with sleep, iron status, contraception and medications. A broad risk calculator can flag the timing pattern but cannot determine the safest treatment strategy.","Family history also matters because migraine has a genetic component, yet genetics does not make attacks inevitable. Use nonmodifiable factors to understand background susceptibility while focusing action on trackable patterns and appropriate medical care." ]},
{heading:"Aura and neurologic symptoms",text:["Some people with migraine experience aura, such as temporary visual, sensory or language symptoms. Aura has specific clinical features and should not be self-diagnosed from any visual disturbance or numbness. First-time neurologic symptoms need appropriate evaluation because stroke, seizure and other conditions can overlap with migraine-like presentations.","If the calculator asks about aura, answer based on an established history rather than guessing. Aura status can also matter to medication and contraceptive discussions, which is another reason a generic score should not be used as a treatment recommendation." ]},
{heading:"Turning the score into a useful diary",text:["The most productive response to a higher score is not fear; it is better data. Track headache days, pain severity, associated nausea or light sensitivity, sleep, meals, hydration, caffeine, menstrual timing where relevant, stress and acute medications. Over time, repeated associations are more useful than one calculated number.","Re-run the calculator only when the underlying pattern changes. The target is fewer disabling headache days and better function, not merely a lower risk score. Discuss frequent, worsening or disabling headaches with a qualified clinician who can evaluate diagnosis, prevention and acute treatment options." ]}
]},
"leveraged-etf-decay-calculator": {title:"Leveraged ETF Decay Calculator", sections:[
{heading:"Why leveraged ETFs do not simply multiply long-term returns",text:["A daily leveraged ETF generally targets a multiple of an index's DAILY return, such as 2x or 3x, before fees and tracking effects. That objective resets each trading day. Over multiple days, compounding means the fund's cumulative return depends on the path of daily gains and losses, not merely the index's start and end values. This is the central concept behind volatility drag or leveraged ETF decay.","If an index rises 10% and then falls 9.09%, it returns to its starting value. A hypothetical 2x product rises 20% on day one and then falls about 18.18% on day two. $100 becomes $120 and then about $98.18. The index is flat, but the leveraged path lost about 1.82% before fees and tracking differences." ]},
{heading:"Daily reset and compounding",text:["Daily reset is not a defect; it is how the product maintains its stated daily exposure. After a gain, the fund must establish leveraged exposure to a larger asset base. After a loss, it resets from a smaller base. Repeating this process creates compounding that can help or hurt depending on the sequence of returns.","In a strong, relatively smooth trend, compounding can produce a multi-day return that is better than simply multiplying the index's total return by the leverage factor. In choppy markets, repeated reversals can erode value. Therefore 'decay' is not a fixed daily fee that can be subtracted mechanically." ]},
{heading:"Volatility drag with a worked example",text:["Consider an index that alternates +5% and -4.7619%, ending approximately flat after two days. A 3x daily product would move roughly +15% and -14.2857%. Starting from $100, it becomes $115 and then about $98.57. The loss occurs even though the underlying index is nearly unchanged because the percentage decline applies to the larger post-gain base.","Increase the size or frequency of these reversals and the gap can become much larger. This is why a calculator needs assumptions about daily volatility or an explicit sequence of returns; annual index return alone is insufficient to reconstruct the leveraged outcome." ]},
{heading:"Trend, volatility and holding period",text:["Three variables dominate interpretation: leverage multiple, volatility and path. Higher leverage magnifies both directional exposure and the compounding effect. Higher volatility creates larger percentage swings to compound. A longer holding period gives those effects more opportunities to accumulate, although a persistent favorable trend can offset or overwhelm drag for a time.","Do not interpret a projected decay percentage as guaranteed loss over a particular holding period. Real markets can trend, gap, reverse and change volatility regimes. The calculator is most useful for showing why the same ending index return can produce different leveraged ETF outcomes under different paths." ]},
{heading:"Inverse leveraged ETFs",text:["Inverse products target negative daily exposure, such as -1x, -2x or -3x. They also reset daily and therefore have the same path-dependence issue. A -2x fund is designed to deliver approximately twice the opposite of one day's index move, not twice the opposite of a one-year index return.","Choppy markets can damage both bullish and inverse leveraged products over time. This surprises users who assume that one of two opposite funds must necessarily profit when the index finishes near its starting point. Daily compounding means both can lose value over the same volatile interval." ]},
{heading:"Fees, financing and tracking difference",text:["Volatility drag is only one source of divergence. Leveraged ETFs also have expense ratios and incur costs associated with obtaining derivative exposure. Futures, swaps, financing conditions, collateral yields, market closures and imperfect rebalancing can create tracking differences relative to the idealized daily multiple.","A simple calculator may model only mathematical compounding and an expense ratio. If so, treat its result as an illustration rather than a forecast of a specific ticker. Product documents and historical daily returns are needed for instrument-specific analysis." ]},
{heading:"What the calculator should compare",text:["A useful comparison shows the unleveraged index path, the naive leverage assumption and the daily-reset leveraged path. The gap between naive multiplication and daily compounding reveals why long-horizon expectations can be misleading. Adding fees separately helps distinguish volatility effects from explicit fund costs.","Run several scenarios: a smooth trend, a volatile sideways market and a sharp drawdown followed by recovery. Keeping the ending index return similar while changing the path demonstrates the mechanism more clearly than a single optimistic return assumption." ]},
{heading:"Risk management and interpretation",text:["Leverage accelerates losses as well as gains, and severe index moves can create very large one-day losses in leveraged products. Investors also face behavioral risk because rapid price changes can lead to poor timing decisions. A calculator cannot determine whether a leveraged ETF is suitable for a particular portfolio, time horizon or risk tolerance.","Use the output to understand exposure mechanics and path dependency. Do not treat a favorable backtest or smooth-return projection as evidence that the same compounding will occur in future markets. For long holding periods, examine multiple volatility regimes and the possibility of deep drawdowns rather than focusing only on average return." ]}
]}
})

export function CalculatorBatch46DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">A detailed explanation of the calculation, assumptions, scenarios, costs, thresholds, limitations and practical interpretation for this specific tool.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}